import{_ as s,a as o,c as n,ac as a}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"第一册：英语初阶 · 全册短语与句型 · 第1–27课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第一册：英语初阶 · 全册短语与句型 · 第1–27课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-1/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 全册短语与句型","link":"/life/english/new-concept/book-1/phrases"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第28–55课","link":"/life/english/new-concept/book-1/phrases-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 全册短语与句型","link":"/life/english/new-concept/book-1/phrases"},"next":{"text":"第一册：英语初阶 · 全册短语与句型 · 第28–55课","link":"/life/english/new-concept/book-1/phrases-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-1/phrases-part-01.md","filePath":"life/english/new-concept/book-1/phrases-part-01.md"}'),l={name:"life/english/new-concept/book-1/phrases-part-01.md"};function i(t,e,r,h,p,c){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="第一册-英语初阶-·-全册短语与句型-·-第1–27课" tabindex="-1">第一册：英语初阶 · 全册短语与句型 · 第1–27课 <a class="header-anchor" href="#第一册-英语初阶-·-全册短语与句型-·-第1–27课" aria-label="Permalink to &quot;第一册：英语初阶 · 全册短语与句型 · 第1–27课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="第一册-英语初阶-·-全册短语与句型" tabindex="-1">第一册：英语初阶 · 全册短语与句型 <a class="header-anchor" href="#第一册-英语初阶-·-全册短语与句型" aria-label="Permalink to &quot;第一册：英语初阶 · 全册短语与句型 {#第一册-英语初阶-·-全册短语与句型}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><h2 id="lesson-1-·-be-动词的一般疑问句" tabindex="-1">Lesson 1 · be 动词的一般疑问句 <a class="header-anchor" href="#lesson-1-·-be-动词的一般疑问句" aria-label="Permalink to &quot;Lesson 1 · be 动词的一般疑问句 {#lesson-1-·-be-动词的一般疑问句}&quot;">​</a></h2><ul><li>excuse me — 引起注意时的礼貌开场</li><li>your bag — 用物主限定词说明归属</li></ul><p><strong>句型示范：</strong> Is this your ticket?</p><p>Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-001">进入本课</a></p><h2 id="lesson-2-·-be-动词的一般疑问句" tabindex="-1">Lesson 2 · be 动词的一般疑问句 <a class="header-anchor" href="#lesson-2-·-be-动词的一般疑问句" aria-label="Permalink to &quot;Lesson 2 · be 动词的一般疑问句 {#lesson-2-·-be-动词的一般疑问句}&quot;">​</a></h2><ul><li>excuse me — 引起注意时的礼貌开场</li><li>your bag — 用物主限定词说明归属</li></ul><p><strong>句型示范：</strong> Is this your notebook?</p><p>Is 前置形成问句，this 指近处的一件物品，your notebook 是表语。notebook 为单数，所以使用 is。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-002">进入本课</a></p><h2 id="lesson-3-·-be-动词的否定和缩写" tabindex="-1">Lesson 3 · be 动词的否定和缩写 <a class="header-anchor" href="#lesson-3-·-be-动词的否定和缩写" aria-label="Permalink to &quot;Lesson 3 · be 动词的否定和缩写 {#lesson-3-·-be-动词的否定和缩写}&quot;">​</a></h2><ul><li>is not — 否定身份或归属</li><li>my coat — 名词前说明所属</li></ul><p><strong>句型示范：</strong> This is not my umbrella.</p><p>This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-003">进入本课</a></p><h2 id="lesson-4-·-be-动词的否定和缩写" tabindex="-1">Lesson 4 · be 动词的否定和缩写 <a class="header-anchor" href="#lesson-4-·-be-动词的否定和缩写" aria-label="Permalink to &quot;Lesson 4 · be 动词的否定和缩写 {#lesson-4-·-be-动词的否定和缩写}&quot;">​</a></h2><ul><li>is not — 否定身份或归属</li><li>my coat — 名词前说明所属</li></ul><p><strong>句型示范：</strong> That is not your coat.</p><p>That 指稍远的单数物品；is not 是系表结构的否定，your coat 说明被否定的所属关系。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-004">进入本课</a></p><h2 id="lesson-5-·-身份介绍与特殊疑问句" tabindex="-1">Lesson 5 · 身份介绍与特殊疑问句 <a class="header-anchor" href="#lesson-5-·-身份介绍与特殊疑问句" aria-label="Permalink to &quot;Lesson 5 · 身份介绍与特殊疑问句 {#lesson-5-·-身份介绍与特殊疑问句}&quot;">​</a></h2><ul><li>this is — 向别人介绍人物</li><li>what make — 询问产品品牌</li></ul><p><strong>句型示范：</strong> This is Eva. She is German.</p><p>第一句用 This is 介绍 Eva；第二句用 She 指代 Eva，German 是国籍形容词，作表语，前面不加 a。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-005">进入本课</a></p><h2 id="lesson-6-·-身份介绍与特殊疑问句" tabindex="-1">Lesson 6 · 身份介绍与特殊疑问句 <a class="header-anchor" href="#lesson-6-·-身份介绍与特殊疑问句" aria-label="Permalink to &quot;Lesson 6 · 身份介绍与特殊疑问句 {#lesson-6-·-身份介绍与特殊疑问句}&quot;">​</a></h2><ul><li>this is — 向别人介绍人物</li><li>what make — 询问产品品牌</li></ul><p><strong>句型示范：</strong> What make is your camera?</p><p>What make 是询问品牌的疑问词组；is 位于主语 your camera 之前。这里 make 是名词，不是“制作”的动词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-006">进入本课</a></p><h2 id="lesson-7-·-a-an-与职业名词" tabindex="-1">Lesson 7 · a/an 与职业名词 <a class="header-anchor" href="#lesson-7-·-a-an-与职业名词" aria-label="Permalink to &quot;Lesson 7 · a/an 与职业名词 {#lesson-7-·-a-an-与职业名词}&quot;">​</a></h2><ul><li>an engineer — 元音音素前用 an</li><li>be a nurse — 说明职业</li></ul><p><strong>句型示范：</strong> My sister is an engineer.</p><p>My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-007">进入本课</a></p><h2 id="lesson-8-·-a-an-与职业名词" tabindex="-1">Lesson 8 · a/an 与职业名词 <a class="header-anchor" href="#lesson-8-·-a-an-与职业名词" aria-label="Permalink to &quot;Lesson 8 · a/an 与职业名词 {#lesson-8-·-a-an-与职业名词}&quot;">​</a></h2><ul><li>an engineer — 元音音素前用 an</li><li>be a nurse — 说明职业</li></ul><p><strong>句型示范：</strong> Are your parents teachers?</p><p>Your parents 是复数主语，问句将 are 提前；teachers 为复数职业，不加 a/an。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-008">进入本课</a></p><h2 id="lesson-9-·-be-形容词" tabindex="-1">Lesson 9 · be + 形容词 <a class="header-anchor" href="#lesson-9-·-be-形容词" aria-label="Permalink to &quot;Lesson 9 · be + 形容词 {#lesson-9-·-be-形容词}&quot;">​</a></h2><ul><li>how are you — 询问近况</li><li>look at — 朝某对象看</li></ul><p><strong>句型示范：</strong> Our new neighbour is very friendly.</p><p>Our new neighbour 是单数主语，is 连接表语 friendly；very 修饰形容词 friendly，说明友好程度。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-009">进入本课</a></p><h2 id="lesson-10-·-be-形容词" tabindex="-1">Lesson 10 · be + 形容词 <a class="header-anchor" href="#lesson-10-·-be-形容词" aria-label="Permalink to &quot;Lesson 10 · be + 形容词 {#lesson-10-·-be-形容词}&quot;">​</a></h2><ul><li>how are you — 询问近况</li><li>look at — 朝某对象看</li></ul><p><strong>句型示范：</strong> Look at the young artist.</p><p>Look 是祈使句谓语，省略主语 you；at 引出观察对象 the young artist，young 在名词前作定语。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-010">进入本课</a></p><h2 id="lesson-11-·-whose-与物主限定词" tabindex="-1">Lesson 11 · whose 与物主限定词 <a class="header-anchor" href="#lesson-11-·-whose-与物主限定词" aria-label="Permalink to &quot;Lesson 11 · whose 与物主限定词 {#lesson-11-·-whose-与物主限定词}&quot;">​</a></h2><ul><li>whose scarf — 询问围巾归谁</li><li>her scarf — 用 her 修饰名词</li></ul><p><strong>句型示范：</strong> Whose scarf is that?</p><p>Whose scarf 是疑问词组，询问归属；is 前置，that 是主语。whose 后接 scarf，不能换成 who&#39;s。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-011">进入本课</a></p><h2 id="lesson-12-·-whose-与物主限定词" tabindex="-1">Lesson 12 · whose 与物主限定词 <a class="header-anchor" href="#lesson-12-·-whose-与物主限定词" aria-label="Permalink to &quot;Lesson 12 · whose 与物主限定词 {#lesson-12-·-whose-与物主限定词}&quot;">​</a></h2><ul><li>whose scarf — 询问围巾归谁</li><li>her scarf — 用 her 修饰名词</li></ul><p><strong>句型示范：</strong> This is his bicycle.</p><p>This 是主语，is 是系动词，his bicycle 是表语；his 在 bicycle 前用作物主限定词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-012">进入本课</a></p><h2 id="lesson-13-·-形容词位置与颜色问句" tabindex="-1">Lesson 13 · 形容词位置与颜色问句 <a class="header-anchor" href="#lesson-13-·-形容词位置与颜色问句" aria-label="Permalink to &quot;Lesson 13 · 形容词位置与颜色问句 {#lesson-13-·-形容词位置与颜色问句}&quot;">​</a></h2><ul><li>what colour — 询问颜色</li><li>a new blue jacket — 新旧在颜色前</li></ul><p><strong>句型示范：</strong> Her new jacket is green.</p><p>Her new jacket 是主语，new 修饰 jacket；green 位于 is 后作表语，表示颜色，不需要冠词。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-013">进入本课</a></p><h2 id="lesson-14-·-形容词位置与颜色问句" tabindex="-1">Lesson 14 · 形容词位置与颜色问句 <a class="header-anchor" href="#lesson-14-·-形容词位置与颜色问句" aria-label="Permalink to &quot;Lesson 14 · 形容词位置与颜色问句 {#lesson-14-·-形容词位置与颜色问句}&quot;">​</a></h2><ul><li>what colour — 询问颜色</li><li>a new blue jacket — 新旧在颜色前</li></ul><p><strong>句型示范：</strong> What colour are your shoes?</p><p>What colour 询问颜色，are 与复数主语 your shoes 一致；不因 colour 是单数而改用 is。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-014">进入本课</a></p><h2 id="lesson-15-·-名词复数与复数-be" tabindex="-1">Lesson 15 · 名词复数与复数 be <a class="header-anchor" href="#lesson-15-·-名词复数与复数-be" aria-label="Permalink to &quot;Lesson 15 · 名词复数与复数 be {#lesson-15-·-名词复数与复数-be}&quot;">​</a></h2><ul><li>these passports — 近处的多本护照</li><li>are you — 询问一人或多人的身份</li></ul><p><strong>句型示范：</strong> These tourists are from Spain.</p><p>These tourists 是复数主语，are from Spain 表来源；these 与复数 tourists 配合，Spain 是国家专名。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-015">进入本课</a></p><h2 id="lesson-16-·-名词复数与复数-be" tabindex="-1">Lesson 16 · 名词复数与复数 be <a class="header-anchor" href="#lesson-16-·-名词复数与复数-be" aria-label="Permalink to &quot;Lesson 16 · 名词复数与复数 be {#lesson-16-·-名词复数与复数-be}&quot;">​</a></h2><ul><li>these passports — 近处的多本护照</li><li>are you — 询问一人或多人的身份</li></ul><p><strong>句型示范：</strong> Are these your passports?</p><p>Are 前置，these 是复数主语，your passports 是复数名词表语；your 的形式不因多人多本护照而改变。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-016">进入本课</a></p><h2 id="lesson-17-·-复数职业与-their" tabindex="-1">Lesson 17 · 复数职业与 their <a class="header-anchor" href="#lesson-17-·-复数职业与-their" aria-label="Permalink to &quot;Lesson 17 · 复数职业与 their {#lesson-17-·-复数职业与-their}&quot;">​</a></h2><ul><li>their jobs — 多人的职业</li><li>office assistants — 办公室助理</li></ul><p><strong>句型示范：</strong> Maya and Leo are office assistants.</p><p>Maya and Leo 是 and 连接的复数主语，are 后接复数职业 office assistants。office 作为名词修饰语保持单数。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-017">进入本课</a></p><h2 id="lesson-18-·-复数职业与-their" tabindex="-1">Lesson 18 · 复数职业与 their <a class="header-anchor" href="#lesson-18-·-复数职业与-their" aria-label="Permalink to &quot;Lesson 18 · 复数职业与 their {#lesson-18-·-复数职业与-their}&quot;">​</a></h2><ul><li>their jobs — 多人的职业</li><li>office assistants — 办公室助理</li></ul><p><strong>句型示范：</strong> Their office is on the first floor.</p><p>Their office 虽由多人拥有，但 office 仍是一个，因此用 is；on the first floor 是地点表语。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-018">进入本课</a></p><h2 id="lesson-19-·-主格和宾格" tabindex="-1">Lesson 19 · 主格和宾格 <a class="header-anchor" href="#lesson-19-·-主格和宾格" aria-label="Permalink to &quot;Lesson 19 · 主格和宾格 {#lesson-19-·-主格和宾格}&quot;">​</a></h2><ul><li>tired and hungry — 并列描述状态</li><li>look at them — 介词后用宾格</li></ul><p><strong>句型示范：</strong> The runners are tired and hungry.</p><p>The runners 是复数主语，are 后接两个由 and 连接的表语 tired 和 hungry；形容词不加复数 s。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-019">进入本课</a></p><h2 id="lesson-20-·-主格和宾格" tabindex="-1">Lesson 20 · 主格和宾格 <a class="header-anchor" href="#lesson-20-·-主格和宾格" aria-label="Permalink to &quot;Lesson 20 · 主格和宾格 {#lesson-20-·-主格和宾格}&quot;">​</a></h2><ul><li>tired and hungry — 并列描述状态</li><li>look at them — 介词后用宾格</li></ul><p><strong>句型示范：</strong> Look at them near the gate.</p><p>Look at 是观察动作，them 是介词 at 的宾语；near the gate 补充被观察者所在的位置。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-020">进入本课</a></p><h2 id="lesson-21-·-which-与-one-的替代" tabindex="-1">Lesson 21 · which 与 one 的替代 <a class="header-anchor" href="#lesson-21-·-which-与-one-的替代" aria-label="Permalink to &quot;Lesson 21 · which 与 one 的替代 {#lesson-21-·-which-与-one-的替代}&quot;">​</a></h2><ul><li>give me — 给我，me 是宾格</li><li>the red one — 避免重复单数名词</li></ul><p><strong>句型示范：</strong> Please give me the empty box.</p><p>Please 表礼貌；give 是祈使句谓语，me 为间接宾语，the empty box 为直接宾语；empty 修饰 box。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-021">进入本课</a></p><h2 id="lesson-22-·-which-与-one-的替代" tabindex="-1">Lesson 22 · which 与 one 的替代 <a class="header-anchor" href="#lesson-22-·-which-与-one-的替代" aria-label="Permalink to &quot;Lesson 22 · which 与 one 的替代 {#lesson-22-·-which-与-one-的替代}&quot;">​</a></h2><ul><li>give me — 给我，me 是宾格</li><li>the red one — 避免重复单数名词</li></ul><p><strong>句型示范：</strong> Which notebook do you want: the red one or the blue one?</p><p>Which notebook 是 want 的疑问宾语；do 帮助构成问句。两个 one 都替代 notebook，red 与 blue 提供选择依据。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-022">进入本课</a></p><h2 id="lesson-23-·-ones-与复数选择" tabindex="-1">Lesson 23 · ones 与复数选择 <a class="header-anchor" href="#lesson-23-·-ones-与复数选择" aria-label="Permalink to &quot;Lesson 23 · ones 与复数选择 {#lesson-23-·-ones-与复数选择}&quot;">​</a></h2><ul><li>the clean ones — 替代复数物品</li><li>give us some — 给我们一些</li></ul><p><strong>句型示范：</strong> Please give us the clean plates.</p><p>Give 后先接表示接受者的宾格 us，再接 the clean plates；plates 是复数，clean 仍不变化。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-023">进入本课</a></p><h2 id="lesson-24-·-ones-与复数选择" tabindex="-1">Lesson 24 · ones 与复数选择 <a class="header-anchor" href="#lesson-24-·-ones-与复数选择" aria-label="Permalink to &quot;Lesson 24 · ones 与复数选择 {#lesson-24-·-ones-与复数选择}&quot;">​</a></h2><ul><li>the clean ones — 替代复数物品</li><li>give us some — 给我们一些</li></ul><p><strong>句型示范：</strong> I want the small ones beside the sink.</p><p>I 是主语，want 是谓语，the small ones 是宾语；ones 指已知的复数物品，beside the sink 补充位置。</p><p><a href="/life/english/new-concept/book-1/unit-01/lesson-024">进入本课</a></p><h2 id="lesson-25-·-there-is-与位置介词" tabindex="-1">Lesson 25 · there is 与位置介词 <a class="header-anchor" href="#lesson-25-·-there-is-与位置介词" aria-label="Permalink to &quot;Lesson 25 · there is 与位置介词 {#lesson-25-·-there-is-与位置介词}&quot;">​</a></h2><ul><li>there is — 引出存在的单数对象</li><li>in the cupboard — 在柜子内部</li></ul><p><strong>句型示范：</strong> There is a clock above the fridge.</p><p>There is 引出新信息 a clock；above the fridge 说明时钟高于冰箱，不保证与冰箱表面接触。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-025">进入本课</a></p><h2 id="lesson-26-·-there-is-与位置介词" tabindex="-1">Lesson 26 · there is 与位置介词 <a class="header-anchor" href="#lesson-26-·-there-is-与位置介词" aria-label="Permalink to &quot;Lesson 26 · there is 与位置介词 {#lesson-26-·-there-is-与位置介词}&quot;">​</a></h2><ul><li>there is — 引出存在的单数对象</li><li>in the cupboard — 在柜子内部</li></ul><p><strong>句型示范：</strong> The kettle is on the shelf.</p><p>The kettle 是已知物品，is 后用 on the shelf 说明它的位置；不是首次介绍“这里有什么”的存在句。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-026">进入本课</a></p><h2 id="lesson-27-·-there-are-与复数位置" tabindex="-1">Lesson 27 · there are 与复数位置 <a class="header-anchor" href="#lesson-27-·-there-are-与复数位置" aria-label="Permalink to &quot;Lesson 27 · there are 与复数位置 {#lesson-27-·-there-are-与复数位置}&quot;">​</a></h2><ul><li>there are — 引出复数物品</li><li>next to — 紧挨着</li></ul><p><strong>句型示范：</strong> There are two lamps beside the sofa.</p><p>There are 引出复数物品 two lamps；beside the sofa 是地点短语。are 与 lamps 的复数相配合。</p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-027">进入本课</a></p>',140)])])}const f=s(l,[["render",i]]);export{b as __pageData,f as default};
